// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;

    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(address actor, address victim) public {
        vm.assume(actor != address(0));
        vm.assume(victim != address(0));
        vm.assume(actor != victim);
        vm.assume(victim != address(this));

        bytes32 role = c.PROPOSER_ROLE();
        // deployer holds TIMELOCK_ADMIN_ROLE and grants the victim the role
        c.grantRole(role, victim);
        assertTrue(c.hasRole(role, victim));

        // a third party (actor != victim) tries to renounce the victim's role
        vm.prank(actor);
        try c.renounceRole(role, victim) {
            // call succeeded
        } catch {
            // call reverted
        }

        // General rule: nobody but the account itself can renounce its role,
        // so the victim's role must still be held regardless of what a third
        // party attempts.
        assertTrue(c.hasRole(role, victim));
    }
}
